import math
import hashlib

class BloomFilter:
    """
    A simple Bloom Filter implementation to provide space-efficient 
    probabilistic data structure to test membership of elements. 
    It uses a bit array and multiple hashing functions to minimize 
    the chance of false positives based on expected items and 
    specified false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.size = self._optimal_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_hash_count(self.size, expected_items)
        self.bit_array = [0] * self.size

    def _optimal_size(self, n: int, p: float) -> int:
        return -int(n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_count(self, m: int, n: int) -> int:
        return max(1, int(round((m / n) * math.log(2))))

    def _hashes(self, item: str) -> list:
        return [int(hashlib.sha256((item + str(i)).encode()).hexdigest(), 16) % self.size for i in range(self.hash_count)]

    def add(self, item: str) -> None:
        for idx in self._hashes(item):
            self.bit_array[idx] = 1

    def contains(self, item: str) -> bool:
        return all(self.bit_array[idx] for idx in self._hashes(item))

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that allows for efficient membership testing 
    of items with a specified false positive rate. The filter uses a bit array 
    and multiple hash functions to minimize the risk of false positives.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal bit array size and number of hash functions
        self.bit_array_size = self._optimal_bit_array_size()
        self.num_hashes = self._optimal_num_hashes()

        # Initialize the bit array with all bits set to 0
        self.bit_array = [0] * self.bit_array_size

    def _optimal_bit_array_size(self) -> int:
        return math.ceil((-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_num_hashes(self) -> int:
        return math.ceil((self.bit_array_size / self.expected_items) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        # Using hashlib to create a hash and then ensuring it falls within bit array size
        hash_object = hashlib.md5((item + str(seed)).encode())
        hash_value = int(hash_object.hexdigest(), 16)
        return hash_value % self.bit_array_size

    def add(self, item: str) -> None:
        for seed in range(self.num_hashes):
            index = self._hash(item, seed)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        for seed in range(self.num_hashes):
            index = self._hash(item, seed)
            if self.bit_array[index] == 0:
                return False
        return True

import hashlib
import math

class BloomFilter:
    """
    A bloom filter implementation using a simple bit array and a set of hash functions.
    The design uses the optimal size of the bit array and the optimal number of hash functions
    based on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._optimal_bit_array_size()
        self.hash_count = self._optimal_hash_count()
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil((-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_hash_count(self) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        """Create a hash for the item using a seed to differentiate hash functions."""
        hash_result = hashlib.md5(f"{item}{seed}".encode()).hexdigest()
        return int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for i in range(self.hash_count):
            idx = self._hash(item, i)
            self.bit_array[idx] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        for i in range(self.hash_count):
            idx = self._hash(item, i)
            if self.bit_array[idx] == 0:
                return False
        return True
